// Info-pop popovers, click-to-open contextual help icons.
//
// Per design: click only (no hover, so touch + accidental brush-by work
// correctly), one popover open at a time, click-away or Escape closes.
// Markup: <span class="info-pop-wrap"><button class="info-pop">…</button>
//          <span class="info-pop-content" role="tooltip" hidden>…</span></span>
// Generated by the `info_pop` macro in templates/_components.html.

(function () {
  let openWrap = null;

  function close(wrap) {
    if (!wrap) return;
    const btn = wrap.querySelector(".info-pop");
    const content = wrap.querySelector(".info-pop-content");
    if (!btn || !content) return;
    btn.setAttribute("aria-expanded", "false");
    content.hidden = true;
    content.classList.remove("is-flipped");
    content.style.maxWidth = "";
    content.style.minWidth = "";
    content.style.left = "";
    if (openWrap === wrap) openWrap = null;
  }

  // The horizontal room a popover has: the viewport, narrowed by every
  // ancestor that clips its overflow. A settings card or a scrolling panel
  // clips what spills past its edge just as the viewport does, so a check
  // against the viewport alone let a popover near a card's right edge open
  // half out of sight (#363).
  function clipBounds(el) {
    let left = 8;
    let right = window.innerWidth - 8;
    for (let a = el.parentElement; a && a !== document.body; a = a.parentElement) {
      const cs = getComputedStyle(a);
      if (cs.overflowX === "visible" && cs.overflowY === "visible") continue;
      const r = a.getBoundingClientRect();
      left = Math.max(left, r.left + 8);
      right = Math.min(right, r.right - 8);
    }
    return { left, right };
  }

  function open(wrap) {
    if (openWrap && openWrap !== wrap) close(openWrap);
    const btn = wrap.querySelector(".info-pop");
    const content = wrap.querySelector(".info-pop-content");
    if (!btn || !content) return;
    btn.setAttribute("aria-expanded", "true");
    content.hidden = false;
    openWrap = wrap;
    // Flip to right-anchored if the panel would overflow the room it has,
    // then, if it is wider than that room, shrink it and pin it to the room's
    // left edge. Measure after the panel is visible so
    // getBoundingClientRect is real.
    requestAnimationFrame(() => {
      const { left, right } = clipBounds(wrap);
      let rect = content.getBoundingClientRect();
      if (rect.right > right) {
        content.classList.add("is-flipped");
        rect = content.getBoundingClientRect();
      }
      if (rect.left < left) {
        const room = Math.max(120, right - left);
        // The stylesheet's min-width would win over max-width alone.
        content.style.minWidth = `${Math.round(Math.min(220, room))}px`;
        content.style.maxWidth = `${Math.round(room)}px`;
        content.classList.remove("is-flipped");
        content.style.left = `${Math.round(left - wrap.getBoundingClientRect().left)}px`;
      }
    });
  }

  // One delegated click handler at the document level, buttons added
  // dynamically (e.g. by editor.js after a preview reload) all work
  // without re-binding.
  document.addEventListener("click", (ev) => {
    const btn = ev.target.closest(".info-pop");
    if (btn) {
      ev.preventDefault();
      ev.stopPropagation();
      const wrap = btn.parentElement;
      if (!wrap || !wrap.classList.contains("info-pop-wrap")) return;
      if (openWrap === wrap) {
        close(wrap);
      } else {
        open(wrap);
      }
      return;
    }
    // Click outside the open popover (and outside its trigger) closes.
    if (openWrap && !openWrap.contains(ev.target)) {
      close(openWrap);
    }
  });

  document.addEventListener("keydown", (ev) => {
    if (ev.key === "Escape" && openWrap) {
      const btn = openWrap.querySelector(".info-pop");
      close(openWrap);
      // Return focus to the trigger so keyboard nav stays predictable.
      if (btn) btn.focus();
    }
  });
})();
